package main

import (
	"os"
	"github.com/amig3n/gwtr/cli"
)

func main() {
	rootCmd := cli.NewCLI()

	args := os.Args[1:]

	if len(args) == 0 {
		// run list by default
		rootCmd.RootCmd.SetArgs([]string{"list"})
	} else if len(args)>=1 && args[0] == "help" {
		// NOTE: have to be extracted, as help is autogenerated and does not work with Find() below
		// if help is passed -> run help with the rest of args
		rootCmd.RootCmd.SetArgs(args)
	} else {
		// check if the first argument is a valid command
		cmd, _, err := rootCmd.RootCmd.Find(os.Args[1:])

		if err != nil || cmd == nil {
			// if not, prepend switch
			args = append([]string{"switch"}, os.Args[1:]...)
		}

		rootCmd.RootCmd.SetArgs(args)
	}

	err := rootCmd.RootCmd.Execute()
	if err != nil {
		os.Exit(1)
	}
}
